import { pythonLanguage } from "@codemirror/lang-python";
import type { Extension } from "@codemirror/state";
import {
  type Completion,
  type CompletionContext,
  type CompletionResult,
} from "@codemirror/autocomplete";
import { parseMixed, type Parser } from "@lezer/common";
import { tags } from "@lezer/highlight";
import type {
  DelimiterType,
  InlineContext,
  MarkdownConfig,
  NodeSpec,
} from "@lezer/markdown";
import { store } from "@/core/state/jotai";
import { variablesAtom } from "@/core/variables/state";

// Node names for the embedded Python interpolation block
const PYTHON = "Python";
const PYTHON_MARK = "PythonMark";

const CHAR_CODES = {
  OPEN_BRACE: 123, // {
  CLOSE_BRACE: 125, // }
};

const DELIMITER: DelimiterType = {
  mark: PYTHON_MARK,
  resolve: PYTHON,
};

/**
 * Build the list of completions from the current variables state.
 */
function variableCompletions(): Completion[] {
  const variables = store.get(variablesAtom);
  return Object.values(variables).map((variable) => ({
    label: variable.name,
    detail: variable.dataType ?? undefined,
    type: "variable",
    boost: 5,
  }));
}

/**
 * Define a Python interpolation parser for Markdown.
 *
 * Handles single-brace interpolation blocks like `{ variable }`, while
 * ignoring escaped double-brace sequences (`{{`) and deferring entirely when
 * the feature is not activated.
 *
 * @param pythonParser CodeMirror {@link Parser} for Python
 * @param isActivated Whether interpolation parsing is enabled
 * @returns Markdown extension
 */
export function parsePython(
  pythonParser: Parser,
  isActivated: () => boolean,
): MarkdownConfig {
  const defineNodes = new Array<NodeSpec>();
  defineNodes.push(
    { name: PYTHON, style: tags.emphasis },
    { name: PYTHON_MARK, style: tags.processingInstruction },
  );

  return {
    defineNodes,
    parseInline: [
      {
        name: PYTHON,
        parse(cx: InlineContext, next: number, pos: number): number {
          // Do nothing when the feature is not activated
          if (!isActivated()) {
            return -1;
          }

          // Ignore escaped double open braces (`{{`)
          if (
            next === CHAR_CODES.OPEN_BRACE &&
            cx.char(pos + 1) === CHAR_CODES.OPEN_BRACE
          ) {
            return -1;
          }

          // Only handle single open/close braces
          if (
            next !== CHAR_CODES.OPEN_BRACE &&
            next !== CHAR_CODES.CLOSE_BRACE
          ) {
            return -1;
          }

          return cx.addDelimiter(
            DELIMITER,
            pos,
            pos + 1,
            next === CHAR_CODES.OPEN_BRACE,
            next === CHAR_CODES.CLOSE_BRACE,
          );
        },
      },
    ],
    wrap: parseMixed((node) => {
      if (node.type.name !== PYTHON) {
        return null;
      }

      // Strip the surrounding braces from the Python parse
      const from = node.from + 1;
      const to = node.to - 1;

      // Ensure valid ranges
      if (from >= to || from < 0 || to < 0) {
        return null;
      }

      return {
        parser: pythonParser,
        overlay: [{ from, to }],
      };
    }),
  };
}

/**
 * Completion source for variable names inside template-style curly brace
 * interpolation blocks (e.g. `{ variable }`).
 *
 * Returns null when the cursor is not inside a valid single-brace block.
 */
export function variableCompletionSource(
  context: CompletionContext,
): CompletionResult | null {
  const textBefore = context.state.sliceDoc(0, context.pos);
  const lastOpenBrace = textBefore.lastIndexOf("{");

  // Must have an open brace before the cursor
  if (lastOpenBrace === -1) {
    return null;
  }

  // A closing brace after the last open brace means we are not inside a block
  const lastCloseBrace = textBefore.lastIndexOf("}");
  if (lastCloseBrace > lastOpenBrace) {
    return null;
  }

  // Ignore escaped double-brace sequences (`{{`)
  const charBeforeOpenBrace = textBefore[lastOpenBrace - 1];
  const charAfterOpenBrace = textBefore[lastOpenBrace + 1];
  if (charBeforeOpenBrace === "{" || charAfterOpenBrace === "{") {
